query:
mutation CreateOneTask($input: TaskCreateInput!) {
  createTask(data: $input) {
    __typename
    assignee {
      __typename
      avatarUrl
      id
      name {
        firstName
        lastName
        __typename
      }
    }
    assigneeId
    attachments {
      edges {
        node {
          __typename
          id
          name
        }
        __typename
      }
      __typename
    }
    bodyV2 {
      blocknote
      markdown
      tiptap
      __typename
    }
    createdAt
    createdBy {
      source
      workspaceMemberId
      name
      context {
        provider
        applicationId
        __typename
      }
      __typename
    }
    deletedAt
    dueAt
    id
    position
    status
    taskTargets {
      edges {
        node {
          __typename
          id
          targetCompany {
            __typename
            domainName {
              primaryLinkUrl
              primaryLinkLabel
              secondaryLinks {
                label
                url
                __typename
              }
              __typename
            }
            id
            name
          }
          targetOpportunity {
            __typename
            id
            name
          }
          targetPerson {
            __typename
            avatarFile {
              fileId
              label
              extension
              url
              __typename
            }
            id
            name {
              firstName
              lastName
              __typename
            }
          }
        }
        __typename
      }
      __typename
    }
    timelineActivities {
      edges {
        node {
          __typename
          id
          linkedRecordCachedName
        }
        __typename
      }
      __typename
    }
    title
    updatedAt
    updatedBy {
      source
      workspaceMemberId
      name
      context {
        provider
        applicationId
        __typename
      }
      __typename
    }
  }
}
